UPDATE grounded_run_control
SET state = 'CANCELLED', generation = generation + 1,
    cancelled_at = UTC_TIMESTAMP(3), updated_at = UTC_TIMESTAMP(3)
WHERE run_id = #{identity.runId} AND owner_key = #{identity.ownerKey}
  AND request_id = #{identity.requestId} AND state = 'RUNNING'
  AND generation = #{identity.generation}
